) AS v(rc_id, st, full_name, result, clear_provisional, result_source);

CREATE TEMP TABLE ca0266_expect ON COMMIT DROP AS
SELECT * FROM (VALUES
('CT','U.S. Representative District 1',2),
('CT','U.S. Representative District 2',2),
('CT','U.S. Representative District 3',2),
('CT','U.S. Representative District 4',2),
('CT','U.S. Representative District 5',2),
('TN','U.S. Representative District 1',7),
('TN','U.S. Representative District 2',4),
('TN','U.S. Representative District 3',7),
('TN','U.S. Representative District 4',4),
('TN','U.S. Representative District 5',4),
('TN','U.S. Representative District 6',4),
('TN','U.S. Representative District 7',4),
('TN','U.S. Representative District 8',8),
('TN','U.S. Representative District 9',4)
) AS v(st, pos, expect);

-- ---------------------------------------------------------------------------
-- PRE-FLIGHT
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM ca0266_target;
  IF n <> 102 THEN RAISE EXCEPTION 'PRE: % rows listed, expected 102', n; END IF;

  SELECT count(*) INTO n
    FROM ca0266_target t
    JOIN essentials.race_candidates rc ON rc.id = t.rc_id AND rc.full_name = t.full_name
    JOIN essentials.races ra ON ra.id = rc.race_id AND ra.position_name ~* '^U\.S\. Representative'
    JOIN essentials.elections e ON e.id = ra.election_id AND e.election_type = 'general'
                               AND e.election_date = '2026-11-03' AND e.state = t.st
   WHERE rc.candidate_status <> 'withdrawn'
     AND (rc.result IS NULL OR (rc.result = t.result AND rc.result_source = t.result_source));
  IF n <> 102 THEN RAISE EXCEPTION 'PRE: only % of 102 rows match id / name / race / state', n; END IF;

  -- Nothing unreviewed in the races this file touches.
  SELECT count(*) INTO n
    FROM essentials.race_candidates rc
   WHERE rc.race_id IN (SELECT rc2.race_id FROM essentials.race_candidates rc2 JOIN ca0266_target t ON t.rc_id = rc2.id)
     AND rc.result IS NULL AND rc.candidate_status <> 'withdrawn'
     AND rc.id NOT IN (SELECT rc_id FROM ca0266_target);
  IF n <> 0 THEN RAISE EXCEPTION 'PRE: % rows in these races were not reviewed', n; END IF;

  RAISE NOTICE 'CA_0266 pre-flight OK';
END $$;

-- ---------------------------------------------------------------------------
-- Record the reconciliation. provisional_until cleared only where the race is complete (rule 5).
-- ---------------------------------------------------------------------------
UPDATE essentials.race_candidates rc
   SET result             = t.result,
       result_source      = t.result_source,
       result_recorded_at = now(),
       last_verified_at   = now(),
       provisional_until  = CASE WHEN t.clear_provisional THEN NULL ELSE rc.provisional_until END,
       updated_at         = now()
  FROM ca0266_target t
 WHERE rc.id = t.rc_id
   AND rc.result IS NULL;

-- ---------------------------------------------------------------------------
-- VERIFY
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int; r record;
BEGIN
  SELECT count(*) INTO n FROM ca0266_target t JOIN essentials.race_candidates rc ON rc.id = t.rc_id
   WHERE rc.result = t.result AND rc.result_source = t.result_source
     AND (NOT t.clear_provisional OR rc.provisional_until IS NULL)
     AND (t.clear_provisional OR rc.provisional_until IS NOT NULL);
  IF n <> 102 THEN RAISE EXCEPTION 'POST: % of 102 rows in the expected end state', n; END IF;

  -- Each race's live field equals the certified field we hold.
  FOR r IN
    SELECT x.st, x.pos, x.expect,
           (SELECT count(*) FROM essentials.race_candidates rc
             WHERE rc.race_id = ra.id AND essentials.is_live_candidate(rc.candidate_status, rc.result)) AS got
      FROM ca0266_expect x
      JOIN essentials.elections e ON e.state = x.st AND e.election_date = '2026-11-03' AND e.election_type = 'general'
      JOIN essentials.races ra ON ra.election_id = e.id AND ra.position_name = x.pos
  LOOP
    IF r.got <> r.expect THEN
      RAISE EXCEPTION 'POST: % % has % live candidates, expected %', r.st, r.pos, r.got, r.expect;
    END IF;
  END LOOP;
  SELECT count(*) INTO n FROM ca0266_expect; IF n <> 14 THEN RAISE EXCEPTION 'POST: % races checked, expected 14', n; END IF;

  RAISE NOTICE 'CA_0266 applied: 102 rows (56 advanced, 46 not_nominated); CT CD1/CD3/CD4 stay flagged for missing certified candidates';
END $$;

COMMIT;
